  /** define Draw Title Screen */
  function p_Draw_Title_Screen(t: T): void {
    if (eq(G.v.Main_State, "Intro")) {
      if (lt(G.v.TitleScreen_Frame, "60")) {
        t.v.nk1 = "0";
      } else {
        if (lt(G.v.TitleScreen_Frame, "70")) {
          t.v.nk1 = num(t.v.nk1) + 0.1;
        } else {
          if (lt(G.v.TitleScreen_Frame, "120")) {
            t.v.nk1 = "1";
          } else {
            if (lt(G.v.TitleScreen_Frame, "130")) {
              t.v.nk1 = num(t.v.nk1) + -0.1;
            } else {
              if (lt(G.v.TitleScreen_Frame, "150")) {
                t.v.nk1 = "0";
              }
            }
          }
        }
      }
      p_SFE_Set_Text_Color_RGBA(t, "255", "255", "255", t.v.nk1);
      p_SFE_Print_Line_Pos_Size_Angle_Bounds_Space_Align_Text(t, "0", "60", "8", "", "", "", "0.2", "c", "", "A GAME BY");
    } else {
      if (eq(G.v.Main_State, "TitleScreen")) {
        p_SFE_Set_Text_Color_RGBA(t, "255", "255", "255", "0.5");
        p_SFE_Print_Line_Pos_Size_Angle_Bounds_Space_Align_Text(t, "-230", "160", "8", "", "", "", "", "l", "", "v.1.2.1");
      }
    }
  }

  /** define SFE | Switch to Font %s */
